// Billing service with dual Stripe + BTC Lightning recurent billing
// Auto-settles to bc1q4f7e66z87mdfj56kz0dj5hvcnpmh0qh4wuv22e

const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const lightning = require('ln-service')({
  network: 'bitcoin',
  socketPath: '/var/run/lightningd/lightning-rpc.sock'
});

async function createRecurringBilling(customerId, plan) {
  // Stripe SaaS billing
  const stripeSubscription = await stripe.subscriptions.create({
    customer: customerId,
    items: [{ price: plan.stripePriceId }],
    payment_settings: { payment_method_type: 'card' }
  });

  // BTC Lightning micropayments
  const lightningInvoice = await lightning.invoice({
    tokens: plan.btcAmountSatoshis,
    memo: `Monthly subscription for ${plan.id}`
  });

  return {
    stripe: stripeSubscription.id,
    lightning: lightningInvoice.payment_request,
    autoSettleTo: 'bc1q4f7e66z87mdfj56kz0dj5hvcnpmh0qh4wuv22e'
  };
}

module.exports = { createRecurringBilling };
